// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address and an array length indicator and a value; we cannot fuzz dynamic arrays directly here,
    // so we fuzz a single target address and a length to construct an array of that length filled with that address.
    function testFuzz_property(address from, address tosAddr, uint256 len) public {
        // admissible domain: require at least one recipient to satisfy require(_tos.length > 0)
        // but keep wide: allow many lengths; bound to a reasonable max to avoid huge loops in test runs
        uint256 boundedLen = bound(len, 1, 10);

        // build the _tos array of boundedLen, all entries = tosAddr
        address[] memory tos = new address[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) {
            tos[i] = tosAddr;
        }

        // Call transfer and capture its returned boolean via try/catch to observe actual return behaviour.
        bool ok;
        try c.transfer(from, tosAddr, tos, 1) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty _tos array the reference implementation returns true.
        // So assertTrue(ok) — the reference C satisfies this for all inputs; the mutant (which returns false)
        // will make this assertion fail for some inputs (any with boundedLen>=1).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, caddress (an adversarial callee), uint v, and array length and elements via bytes
    function testFuzz_property(address from, address /*unused address param kept for fuzz diversity*/, uint256 v, bytes memory tosEncoded) public {
        // Decode tosEncoded into an address[] in a simple wide way: take its bytes and chunk into 20-byte addresses
        // Keep domain wide but require at least one target to satisfy require(_tos.length > 0)
        uint256 maxChunks = tosEncoded.length / 20;
        vm.assume(maxChunks > 0);
        // limit to a reasonable number to avoid excessive gas
        uint256 n = maxChunks;
        if (n > 8) n = 8;
        address[] memory tos = new address[](n);
        for (uint256 i = 0; i < n; i++) {
            uint160 addr = 0;
            for (uint256 j = 0; j < 20; j++) {
                addr = (addr << 8) | uint8(tosEncoded[i * 20 + j]);
            }
            tos[i] = address(addr);
            // ensure not zero address to avoid trivial EOAs; allow any address though
            if (tos[i] == address(0)) tos[i] = address(uint160(i + 1));
        }

        // The fuzzer supplies an address for the callee behavior; since a raw address is an EOA with no code and
        // low-level call to it will succeed, we must deploy an adversarial callee to be a realistic counterparty.
        // Deploy a simple callee that implements transferFrom to accept the call and return nothing.
        // This callee will not revert, so c.transfer should complete and the reference returns true.
        Callee callee = new Callee();

        // Call through c.transfer and observe its returned boolean using try/catch to read the return value
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert for non-empty tos; but if it does, mark ok = false
            ok = false;
        }

        // The general rule: for any non-empty tos array, the reference C returns true. The mutant returns false for some inputs.
        // Assert that c.transfer returned true for this admissible input set.
        assertTrue(ok);
    }
}

contract Callee {
    // accept any transferFrom call, do nothing
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address, an amount v, and the number of tos to exercise loops
    function testFuzz_property(address from, uint256 v, uint8 nTos) public {
        // keep nTos reasonable but allow zero to be filtered by require in transfer
        uint256 len = uint256(nTos);
        vm.assume(len > 0);

        // deploy an adversarial callee that will fail on one specific target address
        BadCallee bad = new BadCallee();

        // build tos array: put one address that will cause call to fail (the BadCallee)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // place the bad callee at index 0 and harmless EOAs elsewhere (use address(this) as harmless)
            tos[i] = (i == 0) ? address(bad) : address(this);
        }

        // call transfer and capture whether it returns (completes) and its return value
        bool ok;
        try c.transfer(from, address(c), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            // if it reverts, record as false (but reference does not revert in given code)
            ok = false;
        }

        // General property: reference implementation always returns true (it ignores callee failures)
        // So assert that c.transfer(...) returned true. The buggy mutant that short-circuits on failing call
        // will return false for these inputs (BadCallee makes the low-level call fail), causing this assert to fail.
        assertTrue(ok);
    }
}

// Adversarial helper: its fallback simulates a failing external call by reverting
contract BadCallee {
    fallback() external payable {
        revert("bad");
    }
}
